package com.ecommerce.model;
import java.math.BigDecimal; import java.sql.Timestamp;
public class Product { private int id,categoryId,stock; private String name,description,imageUrl,categoryName; private BigDecimal price; private boolean active; private Timestamp createdAt;
 public int getId(){return id;} public void setId(int v){id=v;} public int getCategoryId(){return categoryId;} public void setCategoryId(int v){categoryId=v;} public int getStock(){return stock;} public void setStock(int v){stock=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public Timestamp getCreatedAt(){return createdAt;} public void setCreatedAt(Timestamp v){createdAt=v;} public String getCategoryName(){return categoryName;} public void setCategoryName(String v){categoryName=v;} }
